START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM setup."__EFMigrationsHistory" WHERE "MigrationId" = '20260610185915_AddServiceAgreementEntities') THEN
    CREATE TABLE setup."FgsSetupServiceAgreementPricingComponent" (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "TenantId" bigint NOT NULL,
        "CompanyId" bigint NOT NULL,
        "PricingComponentCode" character varying(50) NOT NULL,
        "Name" character varying(200) NOT NULL,
        "PricingComponentTypeCode" character varying(50) NOT NULL,
        "Amount" numeric(18,2) NOT NULL,
        "Description" text,
        "DisplayOrder" smallint NOT NULL DEFAULT 1,
        "CreatedOn" timestamptz NOT NULL DEFAULT (now()),
        "CreatedBy" character varying(100),
        "UpdatedOn" timestamptz,
        "UpdatedBy" character varying(100),
        "IsActive" boolean NOT NULL DEFAULT TRUE,
        CONSTRAINT "PK_FgsSetupServiceAgreementPricingComponent" PRIMARY KEY ("Id"),
        CONSTRAINT "UQ_FgsSetupServiceAgreementPricingComponent_TenantId_CompanyId_PricingComponentCode" UNIQUE ("TenantId", "CompanyId", "PricingComponentCode"),
        CONSTRAINT "CK_FgsSetupServiceAgreementPricingComponent_Amount" CHECK ("Amount" >= 0),
        CONSTRAINT "CK_FgsSetupServiceAgreementPricingComponent_TypeCode" CHECK ("PricingComponentTypeCode" IN ('FIXED','FIRST_SYSTEM','SECOND_SYSTEM','THIRD_SYSTEM','FOURTH_SYSTEM','FIFTH_SYSTEM','ADDITIONAL_SYSTEM')),
        CONSTRAINT "FK_FgsSetupServiceAgreementPricingComponent_FgsTenantCompanyCache_TenantId_CompanyId" FOREIGN KEY ("TenantId", "CompanyId") REFERENCES setup."FgsTenantCompanyCache" ("TenantId", "CompanyId") ON DELETE RESTRICT
    );
    COMMENT ON TABLE setup."FgsSetupServiceAgreementPricingComponent" IS 'Stores reusable service agreement pricing components and their default pricing for a tenant-company. Component types: FIXED (applied once), FIRST_SYSTEM through FIFTH_SYSTEM (per-system tier), ADDITIONAL_SYSTEM (sixth and subsequent systems).';
    COMMENT ON COLUMN setup."FgsSetupServiceAgreementPricingComponent"."PricingComponentTypeCode" IS 'FIXED, FIRST_SYSTEM, SECOND_SYSTEM, THIRD_SYSTEM, FOURTH_SYSTEM, FIFTH_SYSTEM, or ADDITIONAL_SYSTEM.';
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM setup."__EFMigrationsHistory" WHERE "MigrationId" = '20260610185915_AddServiceAgreementEntities') THEN
    CREATE TABLE setup."FgsSetupServiceAgreementTemplate" (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "TenantId" bigint NOT NULL,
        "CompanyId" bigint NOT NULL,
        "TemplateCode" character varying(50) NOT NULL,
        "Name" character varying(200) NOT NULL,
        "Description" text,
        "BillingFrequencyMonths" smallint NOT NULL,
        "MaintenanceFrequencyMonths" smallint NOT NULL,
        "RepairDiscountPercent" numeric(5,2) NOT NULL DEFAULT 0.0,
        "IsAutoRenew" boolean NOT NULL DEFAULT TRUE,
        "DisplayOrder" smallint NOT NULL DEFAULT 1,
        "CreatedOn" timestamptz NOT NULL DEFAULT (now()),
        "CreatedBy" character varying(100),
        "UpdatedOn" timestamptz,
        "UpdatedBy" character varying(100),
        "IsActive" boolean NOT NULL DEFAULT TRUE,
        CONSTRAINT "PK_FgsSetupServiceAgreementTemplate" PRIMARY KEY ("Id"),
        CONSTRAINT "UQ_FgsSetupServiceAgreementTemplate_TenantId_CompanyId_TemplateCode" UNIQUE ("TenantId", "CompanyId", "TemplateCode"),
        CONSTRAINT "CK_FgsSetupServiceAgreementTemplate_BillingFrequencyMonths" CHECK ("BillingFrequencyMonths" IN (1,3,6,12)),
        CONSTRAINT "CK_FgsSetupServiceAgreementTemplate_MaintenanceFrequencyMonths" CHECK ("MaintenanceFrequencyMonths" IN (1,3,6,12)),
        CONSTRAINT "CK_FgsSetupServiceAgreementTemplate_RepairDiscountPercent" CHECK ("RepairDiscountPercent" >= 0 AND "RepairDiscountPercent" <= 100),
        CONSTRAINT "FK_FgsSetupServiceAgreementTemplate_FgsTenantCompanyCache_TenantId_CompanyId" FOREIGN KEY ("TenantId", "CompanyId") REFERENCES setup."FgsTenantCompanyCache" ("TenantId", "CompanyId") ON DELETE RESTRICT
    );
    COMMENT ON TABLE setup."FgsSetupServiceAgreementTemplate" IS 'Stores service agreement templates defining billing frequency, maintenance frequency, repair discounts, and default terms for a tenant-company.';
    COMMENT ON COLUMN setup."FgsSetupServiceAgreementTemplate"."BillingFrequencyMonths" IS 'Billing frequency in months. 1 = Monthly, 3 = Quarterly, 6 = Semi-Annual, 12 = Annual.';
    COMMENT ON COLUMN setup."FgsSetupServiceAgreementTemplate"."MaintenanceFrequencyMonths" IS 'Maintenance frequency in months. 1 = Monthly, 3 = Quarterly, 6 = Semi-Annual, 12 = Annual.';
    COMMENT ON COLUMN setup."FgsSetupServiceAgreementTemplate"."RepairDiscountPercent" IS 'Discount given to service agreement customers on additional repairs.';
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM setup."__EFMigrationsHistory" WHERE "MigrationId" = '20260610185915_AddServiceAgreementEntities') THEN
    CREATE TABLE setup."FgsSetupServiceAgreementTemplateCoverage" (
        "TenantId" bigint NOT NULL,
        "CompanyId" bigint NOT NULL,
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "ServiceAgreementTemplateId" bigint NOT NULL,
        "CoverageTypeCode" character varying(20) NOT NULL,
        "Description" text NOT NULL,
        "DisplayOrder" smallint NOT NULL DEFAULT 1,
        "CreatedOn" timestamptz NOT NULL DEFAULT (now()),
        "CreatedBy" character varying(100),
        "UpdatedOn" timestamptz,
        "UpdatedBy" character varying(100),
        CONSTRAINT "PK_FgsSetupServiceAgreementTemplateCoverage" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_FgsSetupServiceAgreementTemplateCoverage_CoverageTypeCode" CHECK ("CoverageTypeCode" IN ('INCLUDE','EXCLUDE')),
        CONSTRAINT "FK_FgsSetupServiceAgreementTemplateCoverage_FgsTenantCompanyCache_TenantId_CompanyId" FOREIGN KEY ("TenantId", "CompanyId") REFERENCES setup."FgsTenantCompanyCache" ("TenantId", "CompanyId") ON DELETE RESTRICT,
        CONSTRAINT "FK_FgsSetupServiceAgreementTemplateCoverage_ServiceAgreementTemplateId" FOREIGN KEY ("ServiceAgreementTemplateId") REFERENCES setup."FgsSetupServiceAgreementTemplate" ("Id") ON DELETE RESTRICT
    );
    COMMENT ON TABLE setup."FgsSetupServiceAgreementTemplateCoverage" IS 'Stores included or excluded coverage items for a service agreement template.';
    COMMENT ON COLUMN setup."FgsSetupServiceAgreementTemplateCoverage"."ServiceAgreementTemplateId" IS 'Service agreement template that this coverage item belongs to.';
    COMMENT ON COLUMN setup."FgsSetupServiceAgreementTemplateCoverage"."CoverageTypeCode" IS 'INCLUDE or EXCLUDE.';
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM setup."__EFMigrationsHistory" WHERE "MigrationId" = '20260610185915_AddServiceAgreementEntities') THEN
    CREATE TABLE setup."FgsSetupServiceAgreementTemplatePricingComponent" (
        "TenantId" bigint NOT NULL,
        "CompanyId" bigint NOT NULL,
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "ServiceAgreementTemplateId" bigint NOT NULL,
        "PricingComponentCode" character varying(50) NOT NULL,
        "Name" character varying(200) NOT NULL,
        "Amount" numeric(18,2) NOT NULL,
        "DisplayOrder" smallint NOT NULL DEFAULT 1,
        "CreatedOn" timestamptz NOT NULL DEFAULT (now()),
        "CreatedBy" character varying(100),
        "UpdatedOn" timestamptz,
        "UpdatedBy" character varying(100),
        CONSTRAINT "PK_FgsSetupServiceAgreementTemplatePricingComponent" PRIMARY KEY ("Id"),
        CONSTRAINT "UQ_FgsSetupServiceAgreementTemplatePricingComponent_TenantId_CompanyId_TemplateId_ComponentCode" UNIQUE ("TenantId", "CompanyId", "ServiceAgreementTemplateId", "PricingComponentCode"),
        CONSTRAINT "CK_FgsSetupServiceAgreementTemplatePricingComponent_Amount" CHECK ("Amount" >= 0),
        CONSTRAINT "FK_FgsSetupServiceAgreementTemplatePricingComponent_FgsTenantCompanyCache_TenantId_CompanyId" FOREIGN KEY ("TenantId", "CompanyId") REFERENCES setup."FgsTenantCompanyCache" ("TenantId", "CompanyId") ON DELETE RESTRICT,
        CONSTRAINT "FK_FgsSetupServiceAgreementTemplatePricingComponent_ServiceAgreementTemplateId" FOREIGN KEY ("ServiceAgreementTemplateId") REFERENCES setup."FgsSetupServiceAgreementTemplate" ("Id") ON DELETE RESTRICT
    );
    COMMENT ON TABLE setup."FgsSetupServiceAgreementTemplatePricingComponent" IS 'Stores pricing components included in a service agreement template. Rows are a snapshot copied from FgsSetupServiceAgreementPricingComponent when the template is configured and become independent of the master pricing component.';
    COMMENT ON COLUMN setup."FgsSetupServiceAgreementTemplatePricingComponent"."ServiceAgreementTemplateId" IS 'Service agreement template that includes this pricing component snapshot.';
    END IF;
END $EF$;

